import{_ as o,z as t,m as a,ap as s}from"./chunks/framework.bQJNM8pB.js";const i="/adapter-yunhupro/assets/screenshot_2026-04-25_21-06-28.DXkemhGo.png",p=JSON.parse('{"title":"WebSocket 方式接入教程","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/firstime/start-websocket.md","filePath":"markdown/firstime/start-websocket.md","lastUpdated":1786200519000}'),r={name:"markdown/firstime/start-websocket.md"};function l(c,e,n,d,k,b){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="websocket-方式接入教程" tabindex="-1">WebSocket 方式接入教程 <a class="header-anchor" href="#websocket-方式接入教程" aria-label="Permalink to &quot;WebSocket 方式接入教程&quot;">​</a></h1><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>本教程适用于选择 <strong>WebSocket 方式</strong> 接入的用户。</p><p><strong>无需公网 IP</strong>，通过 WebSocket 长连接接收云湖平台的事件推送，配置简单。</p><blockquote><p><strong>前置准备</strong>：请先完成 <a href="./start.html">首次接入指南</a> 中的公共步骤（创建机器人、获取 Token、配置订阅事件）。</p></blockquote><h2 id="_1-配置-websocket-方式" tabindex="-1">1. 配置 WebSocket 方式 <a class="header-anchor" href="#_1-配置-websocket-方式" aria-label="Permalink to &quot;1. 配置 WebSocket 方式&quot;">​</a></h2><p>在 Koishi 的插件市场中找到并安装 <code>adapter-yunhupro</code> 适配器，然后进入配置页面。</p><ol><li><strong>Token</strong>：填入在首次接入指南中获取的机器人 Token</li><li><strong>订阅方式</strong>：选择 <code>websocket</code>（默认，推荐）</li><li><strong>云湖 websocket 地址</strong>：默认为 <code>wss://ws.jwzhd.com/subscribe</code>，通常无需修改</li></ol><p>配置完成后，保存配置即可。</p><p>适配器会自动连接到云湖平台并开始接收消息。</p><p><img src="'+i+'" alt="WebSocket配置示例"></p><h2 id="_2-测试连接" tabindex="-1">2. 测试连接 <a class="header-anchor" href="#_2-测试连接" aria-label="Permalink to &quot;2. 测试连接&quot;">​</a></h2><p>配置完成后进行以下验证：</p><ol><li>保存配置，适配器会自动启动</li><li>查看 Koishi 控制台日志，确认是否显示 <code>WebSocket连接已建立</code></li><li>直接向机器人发送消息测试即可</li></ol><ul><li><strong>私聊</strong> 您的机器人，发送任意消息，例如 <code>status</code>。</li><li>如果您的 Koishi 机器人做出了回应，说明连接已经成功建立。</li></ul><h2 id="_3-websocket-方式排查" tabindex="-1">3. WebSocket 方式排查 <a class="header-anchor" href="#_3-websocket-方式排查" aria-label="Permalink to &quot;3. WebSocket 方式排查&quot;">​</a></h2><p>如果机器人没有响应，请检查以下几点：</p><ul><li>Koishi 服务是否正常运行？</li><li>检查 Koishi 的控制台日志，确认 WebSocket 是否成功连接</li><li>Token 是否正确？</li><li>网络是否能访问 <code>wss://ws.jwzhd.com/subscribe</code>？</li></ul><h2 id="多机器人配置-websocket" tabindex="-1">多机器人配置（WebSocket） <a class="header-anchor" href="#多机器人配置-websocket" aria-label="Permalink to &quot;多机器人配置（WebSocket）&quot;">​</a></h2><p>如果您需要运行多个云湖机器人，请使用 Koishi 的<strong>多开插件功能</strong>：</p><ol><li>在插件列表中找到 <code>adapter-yunhupro</code></li><li>点击「添加实例」按钮</li><li>为每个实例配置不同的 Token</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>WebSocket 方式</strong>：每个实例独立连接，无需额外配置</p></div>',22)])])}const u=o(r,[["render",l]]);export{p as __pageData,u as default};
